CREATE TABLE t_p23442598_alumni_network_app.posts (id SERIAL PRIMARY KEY, user_id INT REFERENCES t_p23442598_alumni_network_app.users(id), author_name VARCHAR(100) NOT NULL, author_initials VARCHAR(4) NOT NULL, author_color VARCHAR(80) NOT NULL DEFAULT 'from-violet-500 to-purple-700', school VARCHAR(100) NOT NULL DEFAULT '', text TEXT NOT NULL, likes_count INT NOT NULL DEFAULT 0, comments_count INT NOT NULL DEFAULT 0, status VARCHAR(20) NOT NULL DEFAULT 'active', created_at TIMESTAMP NOT NULL DEFAULT NOW())
